head.script:
scwin.fn_expressionValue = function(rowIdx, col1Value, col2Value) {
    var returnValue = "";
    returnValue = col2Value;
    var rowData = dataList1.getRowData(rowIdx);
    //계산식
    if (col1Value == "sum") {
        gridView1.setCellColor(rowIdx, "col3", "red");
    } else {
        gridView1.setCellColor(rowIdx, "col3", "blue");
    }
    returnValue = WebSquare.util.setNumber(returnValue);
    console.log(col1Value + " : " + col2Value);
    console.log("=====>" + returnValue);
    return returnValue + "_test";
}
scwin.trigger1_onclick = function(e) {
    var jsonData = [{
            "col1": "sum",
            "col2": "12345.00"
        }, {
            "col1": "avg",
            "col2": "123456.894"
        },
        {
            "col1": "sum",
            "col2": "467890.00"
        }, {
            "col1": "avg",
            "col2": "123456.7"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.trigger3_onclick = function(e) {
    dataList1.removeAll();
};
scwin.trigger4_onclick = function(e) {
    dataList1.insertRow();
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 set, removeAll, insertRow를 클릭한다.
    //1. Run the sample file and click set, removeAll, insertRow.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    // verify step 1. undefined_test값이 정상적으로 보여진다.(이전에는 기존값이 insertRow에 보여짐)
    //1. The undefined_test value is displayed normally.(Previously the existing value is shown in insertRow) 
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').childNodes[0].innerHTML == 'undefined_test'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
